CREATE OR REPLACE FUNCTION transfer_diamonds_atomic(
    p_from_user_id UUID,
    p_to_user_id UUID,
    p_amount BIGINT,
    p_type VARCHAR(32) DEFAULT 'TRANSFER',
    p_require_purchase BOOLEAN DEFAULT TRUE
)
RETURNS TABLE(new_from_balance BIGINT, transaction_id BIGINT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_from_balance BIGINT;
    v_tx_id BIGINT;
    v_first UUID;
    v_second UUID;
BEGIN
    IF p_amount <= 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'INVALID_AMOUNT';
    END IF;
    IF p_from_user_id = p_to_user_id THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'SAME_USER_TRANSFER';
    END IF;

    IF p_require_purchase AND NOT EXISTS (
        SELECT 1 FROM diamond_transactions
        WHERE to_user_id = p_from_user_id AND type = 'PURCHASE'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'PURCHASE_REQUIRED';
    END IF;

    PERFORM ensure_diamond_wallet(p_from_user_id);
    PERFORM ensure_diamond_wallet(p_to_user_id);

    IF p_from_user_id < p_to_user_id THEN
        v_first := p_from_user_id;
        v_second := p_to_user_id;
    ELSE
        v_first := p_to_user_id;
        v_second := p_from_user_id;
    END IF;

    PERFORM 1 FROM diamond_wallets WHERE user_id = v_first FOR UPDATE;
    PERFORM 1 FROM diamond_wallets WHERE user_id = v_second FOR UPDATE;

    UPDATE diamond_wallets
    SET balance = balance - p_amount, updated_at = NOW()
    WHERE user_id = p_from_user_id AND balance >= p_amount
    RETURNING balance INTO v_from_balance;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'INSUFFICIENT_BALANCE';
    END IF;

    UPDATE diamond_wallets
    SET balance = balance + p_amount, updated_at = NOW()
    WHERE user_id = p_to_user_id;

    INSERT INTO diamond_transactions (from_user_id, to_user_id, amount, type, created_at)
    VALUES (p_from_user_id, p_to_user_id, p_amount, p_type, NOW())
    RETURNING id INTO v_tx_id;

    RETURN QUERY SELECT v_from_balance, v_tx_id;
END;
$$;
